import {planBuiltinDeriveBangOutput,proveBuiltinDeriveBangFootprint,isBuiltinDeriveBangFootprint,assertBuiltinDeriveBangFootprint,originalBuiltinDeriveEnclosingOutput} from '../builtin-derive-bang-footprints.mjs';
