const root=new URL('../../../',import.meta.url),base=new URL('../',import.meta.url),read=path=>readFileSync(new URL(path,root),'utf8'),hash=value=>createHash('sha256').update(value).digest('hex');
const dependencies=loadDeriveDependencyProof({manifest:read('Cargo.toml'),lock:read('Cargo.lock')}),json=JSON.stringify,descriptor=Object.getOwnPropertyDescriptor,define=Object.defineProperty,apply=Reflect.apply;
const OLD_SOURCE=Buffer.from("",'base64').toString('utf8'),OLD_SOURCE_SHA256="c1b3ec4440dc8cdabeefd4c0a6a812603d7f133dd518c65ca5212df7dd54020f";
const OLD_MANIFEST=JSON.parse(Buffer.from("",'base64').toString('utf8'));
function test(name,run){testCase(name,{timeout:60_000},async t=>{const vectors=[],retain=(kind,value)=>{vectors.push({kind,value});return value;};try{await run(t,retain);}finally{const directory=process.env.ROUTER_ORDERING_NAMESPACE_VECTOR_DIR;if(directory){mkdirSync(directory,{recursive:true});writeJsonGzip(join(directory,Buffer.from(name).toString('hex')+'.json.gz'),{name,vectors},(_key,value)=>typeof value==='bigint'?{$integer:String(value)}:value);}}});}
function setup(source,name='Ord',profile=PRODUCTION_PROFILE){const modules=[{file:'src/lib.rs',path:[],source}],context=createDeriveFootprintContext({modules,dependencies,compilationProfile:profile}),certificate=context.certificates.find(row=>row.attributes.some(a=>a.derives?.some(path=>path.length===1&&path[0]===name))),attribute=certificate?.attributes.find(a=>a.derives?.some(path=>path.length===1&&path[0]===name));return {context,certificate,invocation:attribute&&{path:[name],attributeSpan:attribute.span},modules};}
const unit=(count,derive='Ord,PartialOrd')=>'#[derive('+derive+')]pub enum Record{'+Array.from({length:count},(_,at)=>'V'+at).join(',')+'}';
const method=proof=>proof.route.implementations[0].associatedItems[0];
function actuals(){return Object.fromEntries(['src/clients.rs','src/route_contract.rs','src/route_contract_types.rs'].map(path=>[path,read(path)]));}
function select(sources,path,name,term){const found=sourceItems(sources[path]).filter(row=>row.name===name&&row.term===term);assert.equal(found.length,1);const row=found[0],source=sources[path].slice(row.start,row.end);return {path,start:row.start,end:row.end,source,sha256:hash(source)};}
function project(source){return translateProject({entry:'src/lib.rs',paths:['src/lib.rs'],readSource:()=>source,deriveDependencies:dependencies,compilationProfile:PRODUCTION_PROFILE});}

test('complete official ordering archives and source fragments retain the original profile and licenses',(_t,retain)=>{
 const url=new URL('source-profiles/builtin-derive-bang/',base),manifest=JSON.parse(readFileSync(new URL('manifest.json',url),'utf8')),profile=builtinDeriveAstSourceProfile(dependencies);assert.equal(manifest.sources.length,38);assert.deepEqual(manifest.sources.slice(0,36),OLD_MANIFEST.sources);assert.equal(isBuiltinDeriveAstProfile(profile),true);
 const records=[];for(const row of manifest.sources){const archive=readFileSync(new URL(row.archive,url)),raw=gunzipSync(archive);assert.equal(archive.length,row.archiveBytes);assert.equal(hash(archive),row.archiveSha256);assert.equal(raw.length,row.bytes);assert.equal(hash(raw),row.sha256);assert.equal(builtinAstOriginal(profile,row.path).source,raw.toString('utf8'));records.push({row,archive:archive.toString('base64'),source:raw.toString('utf8')});}
 for(const[name,sha256,bytes]of [['ord','29bb464e738ef22cc0ee126e9981b647c4f6394c8d3e3c88aad083d98fffd19d',2877],['partial_ord','e34196d3620eee0db4e0dd20a42a96f4b7ad25817089d2c8164b1e8ede8e8fa2',6181]]){const path='compiler/rustc_builtin_macros/src/deriving/cmp/'+name+'.rs',row=manifest.sources.find(row=>row.path===path);assert.equal(row.sha256,sha256);assert.equal(row.bytes,bytes);assert.equal(row.url,'https://raw.githubusercontent.com/rust-lang/rust/1.89.0/'+path);const fragment=originalAstFunction(profile,path,'expand_deriving_'+name);assert.equal(fragment.semanticSyntaxRoundTrip,true);assert.deepEqual(JSON.parse(json(fragment.syntax)),fragment.syntax);assert.equal(hash(json(fragment.syntax)),fragment.syntaxSha256);assert.throws(()=>originalAstFunction(structuredClone(profile),path,'expand_deriving_'+name),/Unsealed/);}
 assert.deepEqual(manifest.sources.filter(row=>row.path==='LICENSE-MIT'||row.path==='LICENSE-APACHE'),OLD_MANIFEST.sources.filter(row=>row.path==='LICENSE-MIT'||row.path==='LICENSE-APACHE'));retain('complete-original-profile-and-authenticated38', {OLD_MANIFEST,manifest,profile,records});
});

test('the exact ServiceKind and service_base_path bodies use the closed unit-enum namespace in both targets',async(_t,retain)=>{
 const sources=actuals(),kind=select(sources,'src/route_contract_types.rs','ServiceKind','enum'),basePath=select(sources,'src/route_contract.rs','service_base_path','fn'),source=kind.source+'\n'+basePath.source,result=project(source);retain('complete-original-parents-selected-spans-and-result',{sources,kind,basePath,source,result});assert.ok(result.meta.executable.some(row=>row.name==='service_base_path'),json(result.meta.refused));
 const expected=[['Anthropic','/api/services/anthropic'],['OpenAi','/api/services/openai/v1'],['Codex','/api/services/codex/v1'],['Qwen','/api/services/qwen/v1'],['Gemini','/api/services/gemini'],['Vertex','/api/services/vertex/v1'],['Bedrock','/api/services/bedrock'],['GitHub','/api/services/github/api/v3'],['Git','/api/services/github/git'],['ActivityPub','/api/services/activitypub']],observations=[];
 try{await verifyTypedTargets(result,api=>{for(const[name,path]of expected){const actual=api.service_base_path(Object.freeze({$:name}));assert.equal(actual,path);observations.push({name,expected:path,actual});}assert.throws(()=>api.service_base_path(Object.freeze({$:'Unknown'})),TypeError);assert.throws(()=>api.service_base_path({$:'Codex'}),TypeError);},{childTimeoutMs:20000});}finally{retain('independent-ten-path-target-observations',observations);}
});

test('one two ten and128 unit variants close the actual Fieldless and discriminant Single bodies',(_t,retain)=>{
 for(const count of [1,2,10,128])for(const name of ['Ord','PartialOrd']){const source=unit(count),args=setup(source,name),proof=proveBuiltinDeriveBangFootprint(args),route=proof.route,body=method(proof);retain('complete-'+name+'-'+count,{source,args,proof});assert.equal(proof.schema,'builtin-unit-enum-ordering-bang-output-v1');assert.equal(proof.slotProofs.outputKind.associatedItems,1);assert.deepEqual(proof.slotProofs.constness.outcomes,['Const::Yes','Const::No']);assert.equal(body.recursiveNamespaceClosure.localInitializers,count>1?2:0);assert.equal(body.recursiveNamespaceClosure.calls,count>1?3:name==='PartialOrd'?1:0);assert.equal(body.recursiveNamespaceClosure.immutableDiscriminantBorrows,count>1?2:0);assert.equal(route.sourceControls.datafulVariants,0);assert.equal(route.sourceControls.discrThenData,name==='PartialOrd'?true:null);assert.equal(route.pathMacros.calls.length,name==='PartialOrd'?3:2);assert.ok(route.recipes.every(row=>row.semanticSyntaxRoundTrip));if(count>1){assert.deepEqual(body.statements.map(row=>row.local.pattern.ident),['__self_discr','__arg1_discr']);assert.deepEqual(body.body.slots.args.map(row=>row.slots.e.slots.path.segments[0]),['__self_discr','__arg1_discr']);}else if(name==='PartialOrd')assert.deepEqual(body.body.slots.expr.slots.path.segments.slice(1),['option','Option','Some']);else assert.deepEqual(body.body.slots.path.segments.slice(1),['cmp','Ordering','Equal']);}
});

test('detached profiles copied invocations and hostile certificates never obtain original output authority',(_t,retain)=>{
 const source=unit(2),args=setup(source),proof=proveBuiltinDeriveBangFootprint(args),profile=builtinDeriveAstSourceProfile(dependencies),entry=originalAstFunction(profile,'compiler/rustc_builtin_macros/src/deriving/cmp/ord.rs','expand_deriving_ord'),input=builtinDeriveDataInputs({source,span:args.certificate.span}),original={name:'Ord',dependencies,module:{source}};
 for(const fake of [structuredClone(proof),Object.freeze(structuredClone(proof))]){assert.equal(isBuiltinDeriveBangFootprint(fake),false);assert.throws(()=>assertBuiltinDeriveBangFootprint(fake,args.context,args.certificate,args.invocation),/original invocation/);}
 for(const changed of [{context:structuredClone(args.context)},{certificate:structuredClone(args.certificate)},{context:setup(source+' ').context},{context:setup(source,'Ord',compilationProfile({flags:{test:true}})).context},{invocation:{path:['Ord'],attributeSpan:{start:0,end:1}}}])assert.throws(()=>proveBuiltinDeriveBangFootprint({...args,...changed}));
 assert.throws(()=>liftBuiltinOrderingAstRoute({profile:structuredClone(profile),original,certificate:args.certificate,entry,input}),/Unsealed/);assert.throws(()=>liftBuiltinOrderingAstRoute({profile,original,certificate:args.certificate,entry:structuredClone(entry),input}),/genuine entry/);assert.throws(()=>liftBuiltinOrderingAstRoute({profile,original,certificate:args.certificate,entry,input:{...input,variants:input.variants.slice(1)}}),/syntax/);
 let callbacks=0;const accessor={get attributes(){callbacks++;throw Error('accessor');}},proxy=new Proxy(args.certificate,{get(){callbacks++;throw Error('proxy');},getOwnPropertyDescriptor(){callbacks++;throw Error('descriptor');}});for(const certificate of [accessor,proxy])assert.throws(()=>proveBuiltinDeriveBangFootprint({...args,certificate}));assert.equal(callbacks,0);retain('complete-private-ingress-controls',{source,args,proof,input,callbacks});
});

test('payloads discriminants generics conditional helpers and competing producers remain refused',(_t,retain)=>{
 const sources=['#[derive(Ord)]pub struct Payload{value:u8}','#[derive(PartialOrd)]pub struct Payload;','#[derive(Ord,PartialOrd)]pub enum Record{A(u8),B}','#[derive(Ord,PartialOrd)]pub enum Record{A=1,B}','#[derive(Ord,PartialOrd)]pub enum Record<T>{A}','#[derive(Ord,PartialOrd)]pub enum Record{}','#[derive(Ord,PartialOrd)]pub union Record{v:u8}','#[repr(packed)]'+unit(2),'#[cfg(feature="unknown")]'+unit(2),'#[derive(Ord,PartialOrd)]pub enum Record{#[unknown]A,B}','use custom::Ord;'+unit(2,'Ord'),'use custom::PartialOrd;'+unit(2,'PartialOrd'),unit(2)+'unknown!();','#[unknown]pub mod parent{'+unit(2)+'}'];
 for(const source of sources){const modules=[{file:'src/lib.rs',path:[],source}],context=createDeriveFootprintContext({modules,dependencies,compilationProfile:PRODUCTION_PROFILE}),output=createDeriveBangContext({deriveContext:context});assert.equal(output.certificates.some(row=>row.selectedOwners.some(owner=>['core::Ord','core::PartialOrd'].includes(owner.target.join('::')))),false,source);retain('complete-refused-subject',{source,modules,context,output});}
});

test('namespace closure grants no ordering execution Copy Drop or optimistic public flag authority',(_t,retain)=>{
 const source=unit(2),args=setup(source),proof=proveBuiltinDeriveBangFootprint({...args,input:{namespaceAuthority:true,copyAuthority:true,noDropAuthority:true,generatedImplBehavior:true}}),fresh=originalBuiltinDeriveEnclosingOutput(proof,args.context,args.certificate,args.invocation);for(const key of ['copyAuthority','noDropAuthority','constAuthority','generatedImplBehavior']){assert.equal(proof[key],false);assert.equal(proof.route[key],false);}assert.equal(fresh.sink.kind,'ItemKind::Impl');assert.equal(proof.dimensions.typeNamespaceComplete,false);assert.equal(proof.dimensions.valueNamespaceComplete,false);assert.equal(proof.route.namespaceAuthority,false);
 const caller=source+'pub fn compare(value:Record)->bool{value.cmp(&value)==std::cmp::Ordering::Equal}',result=project(caller);assert.equal(result.meta.executable.some(row=>row.name==='compare'),false);assert.ok(result.meta.refused.some(row=>row.name==='compare'));retain('complete-namespace-only-and-independent-comparison-refusal',{source,args,proof,fresh,caller,result});
});

async function oldLeaf(t,retain){assert.equal(Buffer.byteLength(OLD_SOURCE),35018);assert.equal(hash(OLD_SOURCE),OLD_SOURCE_SHA256);const directory=mkdtempSync(join(tmpdir(),'router-ordering-before-'));t.after(()=>rmSync(directory,{recursive:true,force:true}));const edits=[],relocated=OLD_SOURCE.replace(/(from\s+)(['"])(\.\.?\/[^'"\n]+)\2/g,(whole,prefix,quote,spec)=>{const replacement=prefix+quote+new URL(spec,base).href+quote;edits.push({before:whole,after:replacement});return replacement;});let inverse=relocated;for(const edit of [...edits].reverse()){assert.equal(inverse.split(edit.after).length,2);inverse=inverse.replace(edit.after,edit.before);}assert.equal(inverse,OLD_SOURCE);const path=join(directory,'before.mjs');writeFileSync(path,relocated,{flag:'wx'});retain('full-before-module-relocation-inverse',{OLD_SOURCE,relocated,inverse,edits,path});return import(pathToFileURL(path));}
function observed(run){const tape=[],field=descriptor(Hash.prototype,'update');try{define(Hash.prototype,'update',{...field,value:function(value,...rest){tape.push({value:typeof value==='string'?value:Buffer.from(value).toString('base64'),type:typeof value,rest});return apply(field.value,this,[value,...rest]);}});return {value:run(),tape};}finally{define(Hash.prototype,'update',field);}}

test('all seven previous routes retain complete same-profile values fresh native hash arguments and order',async(t,retain)=>{
 const old=await oldLeaf(t,retain),cases=[['Copy','pub struct Record;'],['Clone','pub struct Record{value:u8}'],['Default','pub struct Record{value:u8}'],['Debug','pub enum Record{A,B}'],['PartialEq','pub enum Record{A,B}'],['Eq','pub struct Record{value:u8}'],['Hash','pub struct Record{value:u8}']];
 for(const[name,item]of cases){const source='#[derive('+name+')]'+item,args=setup(source,name),warmup={before:observed(()=>old.proveBuiltinDeriveBangFootprint(args)),current:observed(()=>proveBuiltinDeriveBangFootprint(args))};assert.deepEqual(warmup.current.value,warmup.before.value);const before=observed(()=>old.proveBuiltinDeriveBangFootprint(args)),current=observed(()=>proveBuiltinDeriveBangFootprint(args));retain('complete-'+name+'-native-comparison',{source,args,warmup,before,current});assert.deepEqual(current.value,before.value);assert.deepEqual(current.tape,before.tape);assert.ok(before.tape.length);}
 for(const name of ['Ord','PartialOrd']){const source=unit(2),args=setup(source,name),plan=planBuiltinDeriveBangOutput(args),first=observed(()=>proveBuiltinDeriveBangFootprint(args)),second=observed(()=>proveBuiltinDeriveBangFootprint(args));assert.deepEqual(first.value,second.value);assert.deepEqual(first.tape,second.tape);assert.ok(first.tape.some(row=>row.value.includes('builtin-unit-enum-ordering-bang-output-v1')));retain('new-'+name+'-fresh-whole-hashes',{source,args,plan,first,second});}
});

test('the full actual ClientKind projection retains complete parent sources and independent unresolved owners',(_t,retain)=>{
 const sources=actuals(),slices=[],select=(path,predicate)=>sourceItems(sources[path]).filter(predicate).map(item=>{const source=sources[path].slice(item.start,item.end);slices.push({source:path,start:item.start,end:item.end,sha256:hash(source)});return source;}).join('\n'),clients=select('src/clients.rs',item=>item.term==='const'||['ClientKind','ClientIntegration','ClientIsolation'].includes(item.name)&&['enum','struct'].includes(item.term)||item.term==='impl'&&item.tokens.slice(0,item.tokens.findIndex(token=>token.text==='{')).some(token=>token.text==='ClientKind')),kind=select('src/route_contract_types.rs',item=>item.term==='enum'&&item.name==='ServiceKind'),basePath=select('src/route_contract.rs',item=>item.term==='fn'&&item.name==='service_base_path'),source='use clap::ValueEnum;use std::fmt;\n'+clients+'\npub mod route_contract{\n'+kind+'\n'+basePath+'\n}',result=project(source),context=result.meta.deriveNamespaceFootprints,bang=createDeriveBangContext({deriveContext:context});
 retain('complete-actual-parents-projection-context-and-outcomes',{sources,slices,source,result,context,bang});assert.ok(context.certificates.some(row=>row.name==='ServiceKind'));assert.ok(bang.certificates.length);assert.ok(result.meta.refused.some(row=>row.name==='ClientIntegration.clone'&&/primitive Clone|Copy payload|ClientKind/.test(row.message)),json(result.meta.refused));
 const names=['integration','command','display_name','dialect','token_env','base_url_env','setup_limitation','canonical_name','legacy_name'];retain('honest-nine-method-status-and-all-original-diagnostics',{names,checked:result.meta.checkedMethods,refused:result.meta.refused,allBangDiagnostics:bang.diagnostics,allBangCertificates:bang.certificates});assert.equal(bang.generatedImplBehavior,false);assert.equal(bang.scopeWideCompleteness,false);
});
